import React, { useState, useCallback, useMemo } from 'react';
import VisualEditor from './VisualEditor';

const PropertiesPanel = ({ element, selectedInternalElement, onElementUpdate, onElementDelete, onClose }) => {
  const [activeTab, setActiveTab] = useState('visual');
  const [editedPrompt, setEditedPrompt] = useState(element.prompt || '');
  const [editedCode, setEditedCode] = useState(element.content || '');
  const [isRegenerating, setIsRegenerating] = useState(false);

  // Figma-like sections collapsed state
  const [openSections, setOpenSections] = useState({
    layout: true,
    size: true,
    spacing: false,
    typography: false,
    effects: false,
  });

  const toggleSection = useCallback((key) => {
    setOpenSections(prev => ({ ...prev, [key]: !prev[key] }));
  }, []);

  // Обновляем состояние при изменении выбранного элемента
  React.useEffect(() => {
    setEditedPrompt(element.prompt || '');
    setEditedCode(element.content || '');
    setActiveTab('visual');
  }, [element.id, element.prompt, element.content]);

  const handleCodeChange = useCallback((newCode) => {
    setEditedCode(newCode);
    onElementUpdate(element.id, { content: newCode });
  }, [element.id, onElementUpdate]);

  const handleRegenerate = useCallback(async () => {
    if (!editedPrompt.trim()) return;

    setIsRegenerating(true);
    try {
      const response = await fetch('/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          messages: [{ role: 'user', content: editedPrompt }]
        })
      });

      const data = await response.json();
      
      if (data.success && data.visual_content) {
        onElementUpdate(element.id, {
          content: data.visual_content,
          prompt: editedPrompt,
          generatedAt: new Date().toISOString()
        });
        setEditedCode(data.visual_content);
      }
    } catch (error) {
      console.error('Ошибка при регенерации:', error);
    } finally {
      setIsRegenerating(false);
    }
  }, [editedPrompt, element.id, onElementUpdate]);

  return (
    <div className="panel properties-panel">
      <div className="panel-header">
        <span>⚙️ Свойства элемента</span>
        <div style={{ marginLeft: 'auto', display: 'flex', gap: '8px' }}>
          <button 
            onClick={() => onElementDelete?.(element.id)}
            className="btn btn-danger" 
            style={{ padding: '4px 8px', background: '#dc3545', color: 'white', border: 'none', borderRadius: '4px' }}
            title="Удалить элемент"
          >
            🗑️
          </button>
          <button onClick={onClose} className="btn btn-ghost" style={{ padding: '4px 8px' }}>
            ✕
          </button>
        </div>
      </div>

      <div className="panel-content" style={{ display: 'flex', flexDirection: 'column' }}>
        {/* Информация */}
        <div className="p-3 border-b border-gray-200" style={{ position: 'sticky', top: 0, background: '#fff', zIndex: 1 }}>
          <div className="text-sm text-gray-600 mb-1"><strong>ID:</strong> {element.id}</div>
          <div className="text-sm text-gray-600"><strong>Тип:</strong> {element.type}</div>
        </div>

        {/* Вкладки */}
        <div className="flex border-b border-gray-200">
          <button
            onClick={() => setActiveTab('visual')}
            className={`flex-1 py-3 px-4 text-sm font-medium border-b-2 ${
              activeTab === 'visual' ? 'border-blue-500 text-blue-600' : 'border-transparent text-gray-500'
            }`}
          >
            🎨 Visual
          </button>
          <button
            onClick={() => setActiveTab('prompt')}
            className={`flex-1 py-3 px-4 text-sm font-medium border-b-2 ${
              activeTab === 'prompt' ? 'border-blue-500 text-blue-600' : 'border-transparent text-gray-500'
            }`}
          >
            📝 Промпт
          </button>
          <button
            onClick={() => setActiveTab('code')}
            className={`flex-1 py-3 px-4 text-sm font-medium border-b-2 ${
              activeTab === 'code' ? 'border-blue-500 text-blue-600' : 'border-transparent text-gray-500'
            }`}
          >
            💻 Код
          </button>
        </div>

        {/* Содержимое */}
        <div className="flex-1 overflow-auto" style={{ paddingBottom: 8 }}>
          {activeTab === 'visual' && (
            <div className="h-full">
              <VisualEditor
                element={element}
                selectedInternalElement={selectedInternalElement?.artifactId === element.id ? selectedInternalElement.elementId : null}
                onContentChange={(newContent) => {
                  setEditedCode(newContent);
                  onElementUpdate(element.id, { content: newContent });
                }}
                onElementUpdate={onElementUpdate}
                className="h-full"
              />
            </div>
          )}

          {activeTab === 'prompt' && (
            <div className="p-3">
              <label className="block text-sm font-medium text-gray-700 mb-2">Промпт для генерации</label>
              <textarea
                value={editedPrompt}
                onChange={(e) => setEditedPrompt(e.target.value)}
                placeholder="Введите описание..."
                className="w-full h-32 p-3 border border-gray-300 rounded-lg text-sm resize-none focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
              <div className="flex gap-2 mt-3">
                <button onClick={handleRegenerate} className="btn btn-primary flex-1" disabled={!editedPrompt.trim() || isRegenerating}>
                  {isRegenerating ? '⏳ Генерирую...' : '🔄 Перегенерировать'}
                </button>
              </div>
            </div>
          )}

          {activeTab === 'code' && (
            <div className="p-3">
              <label className="block text-sm font-medium text-gray-700 mb-2">HTML/CSS код</label>
              <textarea
                value={editedCode}
                onChange={(e) => handleCodeChange(e.target.value)}
                className="w-full h-64 p-3 border border-gray-300 rounded-lg text-sm font-mono resize-none focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
          )}

          {/* Figma-like sections */}
          <div className="p-3 border-t border-gray-200">
            {/* Layout */}
            <button className="w-full text-left py-2 font-medium" onClick={() => toggleSection('layout')}>Layout</button>
            {openSections.layout && (
              <div className="grid grid-cols-2 gap-2 text-xs mb-3">
                <div>
                  <label>Display</label>
                  <select className="w-full mt-1 px-2 py-1 border border-gray-300 rounded text-xs" value={element.display || ''}
                    onChange={(e) => onElementUpdate(element.id, { display: e.target.value })}>
                    <option value="">Default</option>
                    <option value="flex">flex</option>
                    <option value="grid">grid</option>
                    <option value="block">block</option>
                  </select>
                </div>
                <div>
                  <label>Direction</label>
                  <select className="w-full mt-1 px-2 py-1 border border-gray-300 rounded text-xs" value={element.flexDirection || ''}
                    onChange={(e) => onElementUpdate(element.id, { flexDirection: e.target.value })}>
                    <option value="">Auto</option>
                    <option value="row">row</option>
                    <option value="column">column</option>
                  </select>
                </div>
                <div>
                  <label>Align</label>
                  <select className="w-full mt-1 px-2 py-1 border border-gray-300 rounded text-xs" value={element.alignItems || ''}
                    onChange={(e) => onElementUpdate(element.id, { alignItems: e.target.value })}>
                    <option value="">Auto</option>
                    <option value="flex-start">flex-start</option>
                    <option value="center">center</option>
                    <option value="flex-end">flex-end</option>
                  </select>
                </div>
                <div>
                  <label>Justify</label>
                  <select className="w-full mt-1 px-2 py-1 border border-gray-300 rounded text-xs" value={element.justifyContent || ''}
                    onChange={(e) => onElementUpdate(element.id, { justifyContent: e.target.value })}>
                    <option value="">Auto</option>
                    <option value="flex-start">flex-start</option>
                    <option value="center">center</option>
                    <option value="space-between">space-between</option>
                    <option value="space-around">space-around</option>
                  </select>
                </div>
              </div>
            )}

            {/* Size */}
            <button className="w-full text-left py-2 font-medium" onClick={() => toggleSection('size')}>Size</button>
            {openSections.size && (
              <div className="grid grid-cols-2 gap-2 text-xs mb-3">
                <div>
                  <label>W</label>
                  <input type="number" className="w-full mt-1 px-2 py-1 border border-gray-300 rounded text-xs"
                    value={element.width || 0}
                    onChange={(e) => onElementUpdate(element.id, { width: parseInt(e.target.value) || 0 })} />
                </div>
                <div>
                  <label>H</label>
                  <input type="number" className="w-full mt-1 px-2 py-1 border border-gray-300 rounded text-xs"
                    value={element.height === 'auto' ? '' : (element.height || 0)} placeholder={element.height === 'auto' ? 'auto' : ''}
                    onChange={(e) => onElementUpdate(element.id, { height: e.target.value === '' ? 'auto' : (parseInt(e.target.value) || 0) })} />
                </div>
              </div>
            )}

            {/* Spacing */}
            <button className="w-full text-left py-2 font-medium" onClick={() => toggleSection('spacing')}>Spacing</button>
            {openSections.spacing && (
              <div className="grid grid-cols-4 gap-2 text-xs mb-3">
                {['Top','Right','Bottom','Left'].map((side, idx) => (
                  <div key={side}>
                    <label>{`P${side[0]}`}</label>
                    <input type="number" className="w-full mt-1 px-2 py-1 border border-gray-300 rounded text-xs"
                      value={parseInt((element.padding || '').split(' ')[idx] || 0)}
                      onChange={(e) => {
                        const vals = (element.padding || '0 0 0 0').split(' ').map(v => parseInt(v)||0);
                        vals[idx] = parseInt(e.target.value)||0;
                        onElementUpdate(element.id, { padding: vals.join(' ') });
                      }} />
                  </div>
                ))}
              </div>
            )}

            {/* Typography */}
            <button className="w-full text-left py-2 font-medium" onClick={() => toggleSection('typography')}>Typography</button>
            {openSections.typography && (
              <div className="grid grid-cols-2 gap-2 text-xs mb-3">
                <div>
                  <label>Font size</label>
                  <input type="number" className="w-full mt-1 px-2 py-1 border border-gray-300 rounded text-xs"
                    value={parseInt(element.fontSize || 0) || 14}
                    onChange={(e) => onElementUpdate(element.id, { fontSize: `${parseInt(e.target.value)||14}px` })} />
                </div>
                <div>
                  <label>Font weight</label>
                  <select className="w-full mt-1 px-2 py-1 border border-gray-300 rounded text-xs" value={element.fontWeight || ''}
                    onChange={(e) => onElementUpdate(element.id, { fontWeight: e.target.value })}>
                    <option value="">Default</option>
                    <option value="400">Regular</option>
                    <option value="500">Medium</option>
                    <option value="600">Semibold</option>
                    <option value="700">Bold</option>
                  </select>
                </div>
              </div>
            )}

            {/* Effects */}
            <button className="w-full text-left py-2 font-medium" onClick={() => toggleSection('effects')}>Effects</button>
            {openSections.effects && (
              <div className="grid grid-cols-2 gap-2 text-xs mb-3">
                <div>
                  <label>Border radius</label>
                  <input type="number" className="w-full mt-1 px-2 py-1 border border-gray-300 rounded text-xs"
                    value={parseInt(element.borderRadius || 0) || 0}
                    onChange={(e) => onElementUpdate(element.id, { borderRadius: `${parseInt(e.target.value)||0}px` })} />
                </div>
                <div>
                  <label>Opacity</label>
                  <input type="number" min={0} max={1} step={0.05} className="w-full mt-1 px-2 py-1 border border-gray-300 rounded text-xs"
                    value={parseFloat(element.opacity || 1)}
                    onChange={(e) => onElementUpdate(element.id, { opacity: parseFloat(e.target.value)||1 })} />
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default PropertiesPanel;
